import React, { useState } from 'react';
import { PRODUCTS } from '../../data/products';
import ProductCard from '../../components/product/ProductCard/ProductCard';
import Button from '../../components/common/Button/Button';
import styles from './GiftingPage.module.css';

const GiftingPage = () => {
  const [priceRange, setPriceRange] = useState('all');

  // Define gift price ranges
  const priceRanges = {
    all: { min: 0, max: Infinity, label: 'All Prices' },
    budget: { min: 0, max: 2000, label: 'Under ₹2000' },
    mid: { min: 2000, max: 4000, label: '₹2000 - ₹4000' },
    luxury: { min: 4000, max: Infinity, label: '₹4000+' },
  };

  const filteredProducts = PRODUCTS.filter((p) => {
    const range = priceRanges[priceRange];
    return p.price >= range.min && p.price <= range.max;
  });

  const giftGuide = [
    {
      occasion: 'Anniversary',
      description: 'Celebrate love with timeless pieces',
      products: ['Aurora Solitaire Ring', 'Nova Diamond Pendant'],
    },
    {
      occasion: 'Birthday',
      description: 'Personalized gifts they\'ll treasure',
      products: ['Stardust Hoop Earrings', 'Solstice Chain Bracelet'],
    },
    {
      occasion: 'Wedding Gift',
      description: 'Premium pieces for special occasions',
      products: ['Nova Diamond Pendant', 'Eclipse Bangle'],
    },
    {
      occasion: 'Bridesmaid Gift',
      description: 'Elegant and wearable',
      products: ['Whisper Stud Earrings', 'Solstice Chain Bracelet'],
    },
  ];

  return (
    <div className={styles.page}>
      {/* Page Header */}
      <section className={styles.pageHeader}>
        <div className={styles.headerContent}>
          <h1 className={styles.title}>Gifting</h1>
          <p className={styles.subtitle}>
            The art of giving luxury. Thoughtfully chosen pieces that celebrate your most precious moments.
          </p>
        </div>
      </section>

      {/* Gift Guide Section */}
      <section className={styles.giftGuide}>
        <div className={styles.giftGuideContainer}>
          <h2 className={styles.giftGuideTitle}>Gift Guide</h2>
          <div className={styles.giftGuideGrid}>
            {giftGuide.map((gift, idx) => (
              <div key={idx} className={styles.giftCard}>
                <h3 className={styles.giftOccasion}>{gift.occasion}</h3>
                <p className={styles.giftDescription}>{gift.description}</p>
                <div className={styles.giftProducts}>
                  {gift.products.map((prod, i) => (
                    <span key={i} className={styles.giftProductTag}>
                      {prod}
                    </span>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Filter Section */}
      <section className={styles.filterSection}>
        <div className={styles.filterContainer}>
          <h3 className={styles.filterTitle}>Filter by Price</h3>
          <div className={styles.filterButtons}>
            {Object.entries(priceRanges).map(([key, value]) => (
              <button
                key={key}
                className={`${styles.filterBtn} ${
                  priceRange === key ? styles['filterBtn--active'] : ''
                }`}
                onClick={() => setPriceRange(key)}
              >
                {value.label}
              </button>
            ))}
          </div>
        </div>
      </section>

      {/* Products Grid */}
      <div className={styles.container}>
        {filteredProducts.length > 0 ? (
          <div className={styles.productsGrid}>
            {filteredProducts.map((product) => (
              <ProductCard key={product.id} product={product} />
            ))}
          </div>
        ) : (
          <div className={styles.noResults}>
            <p>No products in this price range.</p>
          </div>
        )}
      </div>

      {/* Gift Wrapping CTA */}
      <section className={styles.ctaSection}>
        <h2 className={styles.ctaTitle}>Complimentary Gift Wrapping</h2>
        <p className={styles.ctaText}>
          Every purchase comes with luxurious gift wrapping and a personalized message card—
          making your gift even more special.
        </p>
        <Button variant="primary" size="lg">
          Learn More About Gift Services
        </Button>
      </section>
    </div>
  );
};

export default GiftingPage;
